CREATE TABLE t1 (c1 INT PRIMARY KEY, c4 INT);
CREATE TABLE t2 (c1 INT PRIMARY KEY, c2 INT NOT NULL);
INSERT INTO t1 (c1, c4) VALUES (8811, 13);
INSERT INTO t2 (c1, c2) VALUES (9623, 3704);
SELECT 'B: top-level INTERSECT ALL', COUNT(*) FROM ((SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON (1)) INTERSECT ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (0))) AS x;
SELECT 'B: DISTINCT over it', COUNT(*) FROM (SELECT DISTINCT * FROM ((SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON (1)) INTERSECT ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (0))) AS vs_d1) AS y;
