CREATE TABLE t2 (c1 int NOT NULL AUTO_INCREMENT, c2 int NOT NULL, c3 decimal(10,2) NOT NULL, c4 varchar(50) NOT NULL, c5 date NOT NULL, PRIMARY KEY (c1));
